// src/js/App.js
import React, { useState, useEffect } from "react";
import "../css/App.css";
import Login from "../jsx/Login";
import Register from "../jsx/Register";
import Contacts from "../jsx/Contacts";
import PrivateChat from "../jsx/PrivateChat";
import GroupChat from "../jsx/GroupChat";
import CreateGroup from "../jsx/CreateGroup";
import { auth, db } from "../js/firebaseConfig"; 
import { onAuthStateChanged, signOut } from "firebase/auth";
import { doc, getDoc } from "firebase/firestore"; 

function App() {
    const [user, setUser] = useState(null);
    const [screen, setScreen] = useState("login");
    const [chatUser, setChatUser] = useState(null);
    const [chatGroup, setChatGroup] = useState(null);

    // ---------- AUTENTICAÇÃO AUTOMÁTICA ----------
    useEffect(() => {
        const unsub = onAuthStateChanged(auth, async (u) => {
            if (u) {
                console.log("🔐 Usuário autenticado:", u);

                try {
                    const userDoc = await getDoc(doc(db, "users", u.uid));
                    if (userDoc.exists()) {
                        console.log("📄 Dados no Firestore:", userDoc.data());
                    } else {
                        console.log("❌ Usuário NÃO existe no Firestore!");
                    }
                } catch (error) {
                    console.error("Erro ao verificar Firestore:", error);
                }

                setUser(u);
                setScreen("private");
            } else {
                setUser(null);
                setScreen("login");
            }
        });
        return () => unsub();
    }, []);

    // ---------- LOGOUT ----------
    const logout = async () => {
        await signOut(auth);
        setUser(null);
        setScreen("login");
    };

    // ========== TELAS SEM LOGIN ==========
    if (!user) {
        if (screen === "register")
            return <Register setScreen={setScreen} />;

        return <Login setUser={setUser} setScreen={setScreen} />;
    }

    // ========== LAYOUT COM LOGIN ==========
    return (
        <div className="whatsapp-container">
            {/* === Sidebar sempre visível === */}
            <Contacts
                currentUser={user}
                setChatUser={setChatUser}
                setChatGroup={setChatGroup}
                setScreen={setScreen}
                logout={logout}
            />

            {/* === Área de conversa que muda === */}
            <div className="chat-area">
                {/* Tela de chat privado */}
                {screen === "private" && chatUser && (
                    <PrivateChat
                        currentUser={user}
                        otherUser={chatUser}
                        onClose={() => {
                            setChatUser(null);
                            setScreen("private");
                        }}
                    />
                )}

                {/* Tela de chat de grupo */}
                {screen === "group" && chatGroup && (
                    <GroupChat
                        currentUser={user}
                        group={chatGroup}
                        onClose={() => {
                            setChatGroup(null);
                            setScreen("private");
                        }}
                    />
                )}

                {/* Tela de criar grupo */}
                {screen === "createGroup" && (
                    <CreateGroup
                        currentUser={user}
                        setScreen={setScreen}
                    />
                )}

                {/* Tela inicial sem nada selecionado */}
                {screen === "private" && !chatUser && (
                    <div className="chat-header">Selecione uma conversa</div>
                )}
            </div>
        </div>
    );
}

export default App;
